const data = $input.item.json;
const query = data.user_query.toLowerCase();

// =========================================================================
// CRISIS PATTERNS - self-harm or suicidal ideation
// These get redirected to crisis resources, NOT just blocked.
// =========================================================================
const crisisPatterns = [
    /\b(kill|end|hurt)\s+(myself|my\s*self)/i,
    /\b(commit|attempt)\s+suicide/i,
    /\bdon'?t\s+want\s+to\s+(live|be\s+alive|exist)/i,
    /\bsuicid(al|e)/i,
    /\bself[-\s]?harm/i,
    /\bend\s+(my|it\s+all|everything)/i,
    /\btake\s+my\s+(own\s+)?life/i
];

// =========================================================================
// HARD BLOCK PATTERNS - overdose, harm, malicious intent
// These get refused outright.
// =========================================================================
const hardBlockPatterns = [
    /\b(how\s+(much|many|to))\s.*\b(overdose|kill|lethal|fatal)/i,
    /\blethal\s+dose/i,
    /\bmaximum\s+(dose|amount)\s+(before|to)\s+(die|death|kill)/i,
    /\bhow\s+to\s+(poison|kill|harm|hurt)\s+(someone|him|her|them)/i,
    /\b(make|create|synthesize)\s+.*(poison|toxin|drug|narcotic)/i,
    /\bget\s+high\s+(on|from|with)/i,
    /\babuse\s+(this|the)\s+(drug|medication|medicine)/i
];

// =========================================================================
// EVALUATION
// Crisis check FIRST - if both crisis and block patterns match, crisis wins
// =========================================================================
let verdict = 'allow';
let reason = null;
let matchedPattern = null;

for (const pattern of crisisPatterns) {
    if (pattern.test(query)) {
        verdict = 'crisis_redirect';
        reason = 'self_harm_indicators';
        matchedPattern = pattern.source;
        break;
    }
}

if (verdict === 'allow') {
    for (const pattern of hardBlockPatterns) {
        if (pattern.test(query)) {
            verdict = 'block';
            reason = 'overdose_or_harm_query';
            matchedPattern = pattern.source;
            break;
        }
    }
}

return {
    json: {
        ...data,
        pre_filter: {
            verdict: verdict,
            reason: reason,
            matched_pattern: matchedPattern
        }
    }
};

// The Postgres RETURNING gave us confirmed UUIDs.
// We need to combine that with the data from the Validate Input node.

const auditConfirmation = $input.item.json;  // from Postgres
const validatedData = $('Validate Input').item.json;  // from earlier node

return {
    json: {
        request_id: auditConfirmation.request_id,
        session_id: auditConfirmation.session_id,
        user_query: validatedData.user_query,
        user_context: validatedData.user_context,
        audit_created_at: auditConfirmation.timestamp
    }
};

const body = $input.item.json.body || $input.item.json;

// Validate the user query exists
if (!body.user_query || typeof body.user_query !== 'string' || !body.user_query.trim()) {
    throw new Error('Missing or empty user_query in request body');
}

// Trim and length-limit the query
const userQuery = body.user_query.trim().substring(0, 2000);

// Generate UUIDs if not provided
function generateUUID() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0;
        const v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
}

const requestId = generateUUID();
const sessionId = body.session_id || generateUUID();

// Sanitize and structure user context
const userContext = body.user_context || {};
const cleanContext = {
    age: typeof userContext.age === 'number' ? userContext.age : null,
    known_conditions: Array.isArray(userContext.known_conditions) ? userContext.known_conditions : [],
    current_medications: Array.isArray(userContext.current_medications) ? userContext.current_medications : [],
    role: ['patient', 'pharmacist', 'physician'].includes(userContext.role) ? userContext.role : 'patient'
};

return {
    json: {
        request_id: requestId,
        session_id: sessionId,
        user_query: userQuery,
        user_context: cleanContext,
        received_at: new Date().toISOString()
    }
};

