if (!rawText) {
    throw new Error('LLM returned empty response. Full response: ' + JSON.stringify(llmResponse));
}

// LLMs sometimes wrap JSON in markdown code blocks despite instructions.
// Strip ```json and ``` if present.
let cleanText = rawText.trim();
cleanText = cleanText.replace(/^```json\s*/i, '').replace(/^```\s*/, '');
cleanText = cleanText.replace(/\s*```$/, '');
cleanText = cleanText.trim();

let classification;
try {
    classification = JSON.parse(cleanText);
} catch (e) {
    throw new Error(`Failed to parse classifier output as JSON. Raw text: ${rawText}`);
}

// Validate the response shape
const validCategories = ['DRUG_INFO', 'DRUG_INTERACTION', 'DOSAGE_QUESTION', 'SAFETY_CONCERN', 'OUT_OF_SCOPE'];
const validUrgencies = ['routine', 'elevated', 'urgent'];

if (!validCategories.includes(classification.category)) {
    classification.category = 'OUT_OF_SCOPE';
    classification._validation_warning = 'Category was invalid, defaulted to OUT_OF_SCOPE';
}

if (!validUrgencies.includes(classification.urgency)) {
    classification.urgency = 'routine';
}

if (typeof classification.confidence !== 'number' || classification.confidence < 0 || classification.confidence > 1) {
    classification.confidence = 0.5;
}

if (!Array.isArray(classification.drugs_mentioned)) {
    classification.drugs_mentioned = [];
}

// Normalize drug names to lowercase
// Common drug name synonyms - international names → US generic names
// (US generic is what OpenFDA / DailyMed uses)
const DRUG_SYNONYMS = {
    'paracetamol': 'acetaminophen',
    'adrenaline': 'epinephrine',
    'noradrenaline': 'norepinephrine',
    'salbutamol': 'albuterol',
    'frusemide': 'furosemide',
    'glibenclamide': 'glyburide',
    'lignocaine': 'lidocaine',
    'dipyrone': 'metamizole',
    'augmentin': 'amoxicillin and clavulanate',
    'panadol': 'acetaminophen',
    'tylenol': 'acetaminophen',
    'advil': 'ibuprofen',
    'motrin': 'ibuprofen',
    'aspirin': 'aspirin',
    'voltaren': 'diclofenac',
    'cataflam': 'diclofenac',
    'brufen': 'ibuprofen',
    'nurofen': 'ibuprofen',
    'buscopan': 'hyoscine butylbromide',
    'flagyl': 'metronidazole',
    'zithromax': 'azithromycin',
    'zovirax': 'acyclovir',
    'crestor': 'rosuvastatin',
    'lipitor': 'atorvastatin',
    'norvasc': 'amlodipine',
    'glucophage': 'metformin',
    'coumadin': 'warfarin',
    'plavix': 'clopidogrel',
    'lasix': 'furosemide',
    'prilosec': 'omeprazole',
    'losec': 'omeprazole',
    'nexium': 'esomeprazole',
    'concor': 'bisoprolol',
    'tenormin': 'atenolol'
};

// Normalize drug names: lowercase, trim, then apply synonyms
classification.drugs_mentioned = classification.drugs_mentioned
    .map(d => typeof d === 'string' ? d.toLowerCase().trim() : '')
    .filter(d => d.length > 0)
    .map(d => DRUG_SYNONYMS[d] || d);  // map to canonical name if known synonym

// Track the original names too for citation purposes
classification._original_drugs_mentioned = $input.item.json.classification?.drugs_mentioned || [];

if (typeof classification.requires_patient_context !== 'boolean') {
    classification.requires_patient_context = false;
}

// Bring forward the original request context
const requestId = $('Carry Forward').item.json.request_id;
const userQuery = $('Carry Forward').item.json.user_query;
const userContext = $('Carry Forward').item.json.user_context;

return {
    json: {
        request_id: requestId,
        user_query: userQuery,
        user_context: userContext,
        classification: classification,
        raw_llm_response: rawText  // keep for audit/debugging
    }
};

