cleanText = cleanText.trim();

let verdict;
try {
    verdict = JSON.parse(cleanText);
} catch (e) {
    // If parsing fails, default to safe behavior
    verdict = {
        verdict: 'modify',
        issues_found: [{severity: 'moderate', description: 'Safety reviewer output could not be parsed'}],
        modified_response: null,
        additional_disclaimer: 'Note: This response was generated automatically. Please verify any clinical decisions with a healthcare professional.',
        rationale: 'Reviewer output unparseable; applying safe default'
    };
}

// Validate verdict shape
if (!['approve', 'modify', 'block'].includes(verdict.verdict)) {
    verdict.verdict = 'modify';  // safer default
}

if (!Array.isArray(verdict.issues_found)) {
    verdict.issues_found = [];
}

// Pull forward all the data we need
const draftData = $('Parse Response DRUG_INFO').item.json;

// Apply the verdict
let finalAnswer = draftData.draft_response.answer;
let finalConfidence = draftData.draft_response.confidence;
let blockReason = null;
let appliedDisclaimer = null;

